'use strict';

// Uncomment the next lines to use your game instance in the browser
const Game = require('../modules/Game.class');
const game = new Game();

const scoreDisplay = document.querySelector('.game-score');
const startBtn = document.querySelector('.button.start');
const cells = document.querySelectorAll('.field-cell');
const msgStart = document.querySelector('.message-start');
const msgWin = document.querySelector('.message-win');
const msgLose = document.querySelector('.message-lose');

function updateView() {
  const state = game.getState().flat();
  const currentStatus = game.getStatus();

  // Оновлюємо клітинки
  cells.forEach((cell, i) => {
    const value = state[i];

    cell.textContent = value || '';
    // Скидаємо класи до базового і додаємо специфічний для значення
    cell.className = 'field-cell';

    if (value) {
      cell.classList.add(`field-cell--${value}`);
    }
  });

  // Оновлюємо рахунок
  scoreDisplay.textContent = game.getScore();

  // Керування кнопкою
  if (currentStatus !== 'idle') {
    startBtn.textContent = 'Restart';
    startBtn.classList.remove('start');
    startBtn.classList.add('restart');
    msgStart.classList.add('hidden');
  }

  // Повідомлення про фінал
  msgWin.classList.toggle('hidden', currentStatus !== 'win');
  msgLose.classList.toggle('hidden', currentStatus !== 'lose');
}

startBtn.addEventListener('click', () => {
  game.start();
  updateView();
});

document.addEventListener('keydown', (e) => {
  if (game.getStatus() !== 'playing') {
    return;
  }

  let moved = false;

  switch (e.key) {
    case 'ArrowLeft':
      moved = game.moveLeft();
      break;
    case 'ArrowRight':
      moved = game.moveRight();
      break;
    case 'ArrowUp':
      moved = game.moveUp();
      break;
    case 'ArrowDown':
      moved = game.moveDown();
      break;
  }

  if (moved) {
    updateView();
  }
});
